<section class="hero"><div class="eyebrow">AfiuCMS</div><h1><?= e($settings['site_name'] ?? 'AfiuCMS Site') ?></h1><p><?= e($settings['site_tagline'] ?? '') ?></p></section><section class="section"><div class="section-head"><h2>Latest posts</h2><a href="/blog">View all</a></div><div class="posts"><?php foreach ($posts as $post): ?><article class="post-card"><div class="date"><?= e(substr((string)$post['published_at'],0,10)) ?></div><h3><a href="/blog/<?= e($post['slug']) ?>"><?= e($post['title']) ?></a></h3><p><?= e($post['excerpt'] ?: 'Open the post to continue reading.') ?></p></article><?php endforeach; ?><?php if (!$posts): ?><div class="empty">Your site is ready. Publish your first post from the AfiuCMS admin panel.</div><?php endif; ?></div></section>
